type User = { id: number; name: string };
const user: User = { id: 1, name: 'Ada' };
console.log(user.name);

interface Repo<T> {
  findById(id: string): Promise<T | null>;
  save(entity: T): Promise<void>;
}

async function loadUser(repo: Repo<User>, id: string) {
  const user = await repo.findById(id);
  if (!user) throw new Error('missing user');
  return user;
}

type Result<T> =
  | { ok: true; value: T }
  | { ok: false; error: string };

function ok<T>(value: T): Result<T> {
  return { ok: true, value };
}

export function assertNever(x: never): never {
  throw new Error(`unexpected value: ${JSON.stringify(x)}`);
}

type DeepReadonly<T> = {
  readonly [K in keyof T]: T[K] extends object ? DeepReadonly<T[K]> : T[K];
};

function freezeConfig<T extends object>(config: T): DeepReadonly<T> {
  return Object.freeze(config) as DeepReadonly<T>;
}

async function retry<T>(fn: () => Promise<T>, attempts = 3): Promise<T> {
  let lastError: unknown;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError;
}

export class EventBus<Events extends Record<string, unknown>> {
  private listeners = new Map<keyof Events, Set<Function>>();
  on<K extends keyof Events>(event: K, cb: (payload: Events[K]) => void) {
    const set = this.listeners.get(event) ?? new Set();
    set.add(cb);
    this.listeners.set(event, set);
  }
}
